// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.36;

interface RootI {
    function f() external;
    function g() external;
}
interface RootJ { function f() external; }
abstract contract Shared is RootI, RootJ {
    function f() external virtual override(RootI, RootJ);
}
abstract contract ImplementsF is Shared {
    function f() external override {}
}
abstract contract ImplementsG is Shared {
    function g() external override {}
}
contract Combined is ImplementsF, ImplementsG {}

abstract contract GetterBase {
    struct Pair { uint256 x; string text; }
    struct Complex {
        uint256 scalar;
        mapping(address => uint256) ignoredMapping;
        uint256[] ignoredArray;
        bytes blob;
        string text;
        uint256[2] ignoredFixedArray;
    }
    function mapped(address key) external virtual returns (uint256, string memory);
    function direct() external virtual returns (uint256, string memory);
    function complex() external virtual returns (uint256, bytes memory, string memory);
}
contract GetterImpl is GetterBase {
    mapping(address => Pair) public override mapped;
    Pair public override direct;
    Complex public override complex;
}
